actions.script:
const L = (text) => text.length > 255 ? text : ec.l10n.localize(text)
hasAccount = false
deliveredHere = false
if (!emailAccountId) return
const detail = ec.service.sync().name('org.moqui.comms.MailSettingsServices.get#MailAccountDetail').parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError() || !detail?.found) { finishError = ec.message.getErrorsString(); ec.message.clearErrors(); return }
hasAccount = true
const account = detail.account || {}
const server = detail.server || {}
const options = detail.options || {}
const security = (value) => value === 'ssl' ? 'SSL/TLS' : (value === 'starttls' ? 'STARTTLS' : L('no security'))
const windowText = options.syncWindowDays ? ({'30': L('the last 30 days'), '90': L('the last 3 months'), '365': L('the last year')}[options.syncWindowDays]
    || ec.resource.expand('the last ${n} days', '', {n: options.syncWindowDays})) : L('all of it')
const hosted = account.accountKindEnumId === 'EakHosted'
deliveredHere = !server.storeHost && (hosted || account.isShared === true)
review = {accountName: account.accountName, emailAddress: account.emailAddress,
    kindText: hosted ? L('Hosted') : (account.isShared ? L('Shared') : L('Just mine')),
    incomingText: server.storeHost ? (server.storeKind === 'pop' ? 'POP ' : 'IMAP ') + server.storeHost + ':' + server.storePort + ' · ' + security(server.storeSecurity)
        : (deliveredHere ? L('The mail gateway delivers it here') : ''),
    outgoingText: server.smtpHost ? 'SMTP ' + server.smtpHost + ':' + server.smtpPort + ' · ' + security(server.smtpSecurity)
        : (deliveredHere ? L('Replies go out through the gateway') : ''),
    windowText: windowText, filingText: options.recordFilingEnumId === 'ErfAllMatches' ? L('Every message with a known contact goes on their records')
        : L('Only the mail you link goes on a record'),
    membersText: Array.from(detail.memberList || []).map((member) => member.name + ' (' + member.permissionText + ')').join(', ') || (account.isShared ? L('Nobody yet') : '')}
reviewShared = account.isShared === true
finish = {emailAccountId: emailAccountId}
